def solve(expr):
    def apply_op():
        op = ops.pop()
        b = vals.pop()
        a = vals.pop()
        if op == '+':
            vals.append(a + b)
        elif op == '-':
            vals.append(a - b)
        elif op == '*':
            vals.append(a * b)
        elif op == '/':
            vals.append(a // b)

    vals, ops = [], []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i].isdigit():
            j = i
            while i < len(expr) and expr[i].isdigit():
                i += 1
            vals.append(int(expr[j:i]))
        elif expr[i] in '+-*/':
            while ops and ops[-1] in '*/' and expr[i] in '+-':
                apply_op()
                ops.pop()
            ops.append(expr[i])
            i += 1
        elif expr[i] == '(':
            ops.append(expr[i])
            i += 1
        elif expr[i] == ')':
            while ops[-1] != '(':
                apply_op()
            ops.pop()
            i += 1
    while ops:
        apply_op()
    return vals[0]

# Example usage:
print(solve("1 + 2 * 3"))  # Output: 7
print(solve("(1 + 2) * 3"))  # Output: 9
print(solve("10 / 2 - 1"))  # Output: 4
